// @ts-strict-ignore
import styles from "./input-field.module.less";
import { FormField, assignToRefs, InputModeTypes } from "@/core/helpers/form-builder";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";
import { FocusEventHandler, KeyboardEventHandler, Ref } from "react";
import { multipleClassNames } from "@/core/helpers/string-helper";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import InputHelperText from "@/core/components/primitives/input-helper-text/input-helper-text";
import InputError from "@/core/components/primitives/input-error/input-error";

/*  autoComplete values per https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/autocomplete (2022-09-21) */
export type autoCompleteValues =
  | "on"
  | "off"
  | "name"
  | "honorific-prefix"
  | "given-name"
  | "additional-name"
  | "family-name"
  | "honorific-suffix"
  | "nickname"
  | "email"
  | "username"
  | "new-password"
  | "current-password"
  | "one-time-code"
  | "organization-title"
  | "organization"
  | "street-address"
  | "address-line1"
  | "address-line2"
  | "address-line3"
  | "address-level4"
  | "address-level3"
  | "address-level2"
  | "address-level1"
  | "country"
  | "country-name"
  | "postal-code"
  | "cc-name"
  | "cc-given-name"
  | "cc-additional-name"
  | "cc-family-name"
  | "cc-number"
  | "cc-exp"
  | "cc-exp-month"
  | "cc-exp-year"
  | "cc-csc"
  | "cc-type"
  | "transaction-currency"
  | "transaction-amount"
  | "language"
  | "bday"
  | "bday-day"
  | "bday-month"
  | "bday-year"
  | "sex"
  | "tel"
  | "tel-country-code"
  | "tel-national"
  | "tel-area-code"
  | "tel-local"
  | "tel-extension"
  | "impp"
  | "url"
  | "photo";

export type InputFieldProps = {
  type?: "text" | "number" | "date" | "search" | "time";
  className?: string;
  inputMode?: InputModeTypes;
  value?: string;
  name?: string;
  label?: string;
  placeholder?: string;
  onChange?: (name: string, value: string) => void;
  onInput?: (name: string, value: string) => void;
  focus?: boolean;
  autoComplete?: autoCompleteValues;
  helperText?: string;
  errorText?: string;
  isValid?: boolean;
  isEditable?: boolean;
  isDisabled?: boolean;
  isRequired?: boolean;
  inputClassName?: string;
  formField?: FormField;
  onBlur?: FocusEventHandler<HTMLInputElement>;
  onKeyUp?: KeyboardEventHandler<HTMLInputElement>;
  onKeyDown?: KeyboardEventHandler<HTMLInputElement>;
  additionalText?: string;
  inputRef?: Ref<HTMLInputElement>;
  icon?: IconName;
  onClick?: () => void;
  /** Used to style grouped inputs that has a common error message (e.g. birth date) **/
  isGroupedInput?: boolean;
} & Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  | "ref"
  | "id"
  | "type"
  | "value"
  | "name"
  | "autoFocus"
  | "inputMode"
  | "autoComplete"
  | "onChange"
  | "onInput"
  | "onBlur"
  | "onKeyUp"
  | "onKeyDown"
>;

const InputField = (props: InputFieldProps) => {
  let {
    type,
    className,
    inputMode,
    value,
    name,
    label,
    placeholder,
    onChange,
    onInput,
    focus,
    autoComplete,
    helperText,
    errorText,
    isValid,
    isEditable,
    isDisabled,
    isRequired,
    inputClassName,
    formField,
    onBlur: propsOnBlur,
    onKeyUp: propsOnKeyUp,
    onKeyDown: propsOnKeyDown,
    additionalText,
    inputRef,
    icon,
    onClick,
    isGroupedInput,
    ...rest
  } = props;

  if (formField) {
    name = name ? name : formField.name;
    value = value ? value : formField.value;
    isValid = typeof isValid === "boolean" ? isValid : formField.isValid;
    helperText = helperText ? helperText : formField.helperText;
    errorText = errorText ? errorText : formField.errorText;
    isEditable = typeof isEditable === "boolean" ? isEditable : formField.isEditable;
    placeholder = placeholder ? placeholder : formField.placeholder;
    isRequired = isRequired ? isRequired : formField.isRequired;
    label = label ? label : formField.label;
    autoComplete = autoComplete ? autoComplete : formField.autoComplete;
    inputMode = inputMode ? inputMode : formField.inputMode;
  }

  if (isEditable === false || (formField && formField.isEditable === false)) {
    isDisabled = true;
  }

  const displayError = isValid === false;
  const errorId = name ? `${name}-error` : undefined;

  // Phone fields keep inputMode="tel" so mobile users get the number pad, but a tel input is still a
  // text input that accepts letters. Strip anything that isn't valid in a phone number (digits, +, -,
  // spaces) as it's typed. Keyed on validationType so email/contact/numeric fields are untouched.
  const isPhoneField = formField?.validationType === "PHONE";
  const sanitizeValue = (rawValue: string) => (isPhoneField ? rawValue.replace(/[^\d+\s-]/g, "") : rawValue);

  const onBlur = (event) => {
    if (propsOnBlur && typeof propsOnBlur === "function") {
      propsOnBlur(event);
    }
  };

  /** Native input onKeyUp */
  const onKeyUp = (event) => {
    if (propsOnKeyUp && typeof propsOnKeyUp === "function") {
      propsOnKeyUp(event);
    }
  };

  /** Native input onKeyDown */
  const onKeyDown = (event) => {
    if (propsOnKeyDown && typeof propsOnKeyDown === "function") {
      propsOnKeyDown(event);
    }
  };

  const getInputMode = () => {
    if (inputMode) {
      return inputMode;
    }

    if (type === "number") {
      return "numeric";
    }

    return undefined;
  };

  return (
    <div
      className={multipleClassNames(
        styles.wrapper,
        isDisabled && styles.disabled,
        isGroupedInput && styles.groupedInput,
        className,
      )}
    >
      <div className={styles.innerWrapper} onClick={onClick}>
        {label && (
          <InputLabel
            label={label}
            inputName={name}
            additionalText={additionalText}
            isRequired={isRequired}
            isGroupedInput={isGroupedInput}
          />
        )}
        <div className={styles.inputWrapper}>
          <input
            ref={(e) => assignToRefs(e, inputRef, formField?.inputRef)}
            id={name ? name : undefined}
            type={type ? type : "text"}
            tabIndex={0}
            data-has-icon={!!icon}
            data-has-on-click={!!onClick}
            className={multipleClassNames(styles.input, displayError && styles.inputError, inputClassName)}
            value={value ? value : ""}
            name={name}
            disabled={isDisabled}
            autoFocus={focus}
            inputMode={getInputMode()}
            placeholder={placeholder}
            autoComplete={autoComplete ? autoComplete : "off"}
            aria-invalid={displayError || undefined}
            aria-describedby={displayError && errorId ? errorId : undefined}
            onChange={(event) => onChange?.(event.target.name, sanitizeValue(event.target.value))}
            onInput={(event) => onInput?.(event.currentTarget.name, sanitizeValue(event.currentTarget.value))}
            onBlur={(event) => onBlur(event)}
            onKeyUp={(event) => onKeyUp(event)}
            onKeyDown={(event) => onKeyDown(event)}
            {...rest}
          />
          {icon && (
            <Icon
              name={icon}
              size="xl"
              className={`${styles.inputFieldIcon} ${isDisabled ? styles.disabledIcon : ""}`}
            />
          )}
          {helperText && <InputHelperText helperText={helperText} />}
          <InputError
            id={errorId}
            showError={displayError}
            isRequired={isRequired}
            errorText={errorText}
            validationType={formField?.validationType}
          />
        </div>
      </div>
    </div>
  );
};

export default InputField;
